"use strict";

function renderStreamingMarkdown(blocks, options = {}) {
  const freeze = options.freezeCompletedBlocks === true;
  const completed = blocks.filter((block) => block.completed);
  return {
    completedBlockRenderCount: completed.reduce(
      (count, block) => count + (freeze ? 1 : block.updates),
      0,
    ),
  };
}

module.exports = { renderStreamingMarkdown };
